-- ShahkotPK v12.4.0 — Verified Shahkot City Information
SET NAMES utf8mb4;


CREATE TABLE IF NOT EXISTS city_information_settings_v1240 (
 tenant_id BIGINT NOT NULL DEFAULT 0,
 enabled TINYINT NOT NULL DEFAULT 1,
 page_title VARCHAR(190) NOT NULL DEFAULT 'Shahkot City Information',
 hero_title VARCHAR(220) NOT NULL DEFAULT 'Shahkot, Punjab — Verified City Guide',
 hero_intro VARCHAR(1200) NULL,
 show_sources TINYINT NOT NULL DEFAULT 1,
 show_scope_badges TINYINT NOT NULL DEFAULT 1,
 last_verified DATE NULL,
 updated_by BIGINT NULL,
 updated_at DATETIME NULL,
 PRIMARY KEY(tenant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS city_information_sections_v1240 (
 tenant_id BIGINT NOT NULL DEFAULT 0,
 section_key VARCHAR(60) NOT NULL,
 title VARCHAR(190) NOT NULL,
 subtitle VARCHAR(700) NULL,
 sort_order INT NOT NULL DEFAULT 10,
 enabled TINYINT NOT NULL DEFAULT 1,
 updated_at DATETIME NULL,
 PRIMARY KEY(tenant_id,section_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS city_information_items_v1240 (
 id BIGINT NOT NULL AUTO_INCREMENT,
 tenant_id BIGINT NOT NULL DEFAULT 0,
 item_key VARCHAR(100) NOT NULL,
 section_key VARCHAR(60) NOT NULL,
 label VARCHAR(190) NOT NULL,
 value_text VARCHAR(1000) NOT NULL,
 detail_text VARCHAR(2200) NULL,
 scope_label VARCHAR(120) NULL,
 source_key VARCHAR(80) NULL,
 source_url VARCHAR(1000) NULL,
 source_title VARCHAR(300) NULL,
 verified_on DATE NULL,
 sort_order INT NOT NULL DEFAULT 10,
 featured TINYINT NOT NULL DEFAULT 0,
 enabled TINYINT NOT NULL DEFAULT 1,
 updated_at DATETIME NULL,
 PRIMARY KEY(id), UNIQUE KEY uq_city_info_item(tenant_id,item_key), KEY idx_city_info_section(tenant_id,section_key,enabled,sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS city_information_sources_v1240 (
 tenant_id BIGINT NOT NULL DEFAULT 0,
 source_key VARCHAR(80) NOT NULL,
 source_title VARCHAR(300) NOT NULL,
 source_url VARCHAR(1000) NOT NULL,
 source_type VARCHAR(80) NOT NULL DEFAULT 'official',
 last_verified DATE NULL,
 enabled TINYINT NOT NULL DEFAULT 1,
 updated_at DATETIME NULL,
 PRIMARY KEY(tenant_id,source_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;































































































